package com.falconenergy.repository;
import com.falconenergy.entity.TransportPriceRange; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
public interface TransportPriceRangeRepository extends JpaRepository<TransportPriceRange,Long> { @Query("select r from TransportPriceRange r where r.fuelProduct.id=:productId and r.status='ACTIVE' and r.effectiveDate<=:date and :quantity between r.minLitres and r.maxLitres order by r.effectiveDate desc") List<TransportPriceRange> matches(@Param("productId") Long productId,@Param("quantity") BigDecimal quantity,@Param("date") LocalDate date); @Query("select count(r)>0 from TransportPriceRange r where r.fuelProduct.id=:productId and r.id<>coalesce(:excludeId,-1) and r.minLitres<=:max and r.maxLitres>=:min") boolean overlaps(@Param("productId") Long productId,@Param("min") BigDecimal min,@Param("max") BigDecimal max,@Param("excludeId") Long excludeId); }
